        label = "Remove bodies after", description = "How long a dead event NPC stays." },
}
local Tune = Open77.tunables.declare(GM.settingDefs)
function GM.setting(key) return Tune[key] end

-- The rest of the code keeps reading GM.<name>; each read goes to the live value.
local live = {
    lootMethod = true, lootResource = true, lootExport = true, lootShare = true, lootMinSeconds = true,
    lootGroundSeconds = true, objectiveGrace = true, objectiveDisplay = true, interactPrompt = true, npcDistance = true, eventDistance = true, audienceRadius = true, bossBarRadius = true,
    maxSquad = true, corpseSeconds = true, mapMarker = true, bossBarStyle = true, announceBosses = true,
}
for _, key in ipairs({ "announceMethod", "announceResource", "announceExport", "announceTitle", "announceSeconds",
    "msgBossAppeared", "msgBossHealth", "msgBossDefeated", "msgCrashWarning", "msgCrashSurvivors", "msgBossfightIntro",
    "msgChimeraGas", "msgChimeraCore", "gasEnabled", "gasDamage", "gasRadius", "gasSeconds", "gasPause", "gasLook",
    "coreStart", "coreHits", "corePulse", "deathShow", "stayDown", "deathWreckSeconds" }) do
    live[key] = true
end
setmetatable(GM, { __index = function(_, key) if live[key] then return Tune[key] end end })

local scaling = { enabled = "scaleHealth", radius = "scaleRadius", perPlayer = "scalePerPlayer", maxPlayers = "scaleMaxPlayers" }
GM.scaling = setmetatable({}, { __index = function(_, key) if scaling[key] then return Tune[scaling[key]] end end })
setmetatable(GM.av, { __index = function(_, key) if key == "blastDamage" then return Tune.crashDamage end end })
